// ============================================================================
// Ethernet_AVB_TSN_apb: APB4 register wrapper around Ethernet_AVB_TSN_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Ethernet_AVB_TSN.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Ethernet_AVB_TSN.md
// ============================================================================
module Ethernet_AVB_TSN_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [3:0] q_valid,
  input logic [43:0] q_len,
  output logic [3:0] q_pop,
  output logic [1:0] tx_tc,
  output logic [10:0] tx_len,
  output logic [63:0] tx_ts
);
  localparam logic [31:0] ID_VALUE = 32'h54530200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [20:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd21) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_cfg_inc_ns;
  logic [15:0]   c_cfg_inc_frac;
  logic          c_time_set;
  logic [63:0]   c_time_set_ns;
  logic          c_time_adj;
  logic [31:0]   c_time_adj_ns;
  logic [63:0]   c_time_ns;
  logic          c_gcl_en;
  logic [63:0]   c_gcl_base;
  logic [23:0]   c_gcl_cycle;
  logic [2:0]    c_gcl_last;
  logic          c_gcl_we;
  logic [2:0]    c_gcl_waddr;
  logic [3:0]    c_gcl_wgates;
  logic [23:0]   c_gcl_wivl;
  logic [3:0]    c_cbs_en;
  logic [35:0]   c_cbs_idle;
  logic          c_tx_start;
  logic          c_tx_busy;
  logic          c_gcl_running;
  logic [2:0]    c_gcl_entry;
  logic [3:0]    c_gate_state;
  logic          c_cycle_start;
  logic [79:0]   c_cbs_credit;
  Ethernet_AVB_TSN_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_inc_ns(c_cfg_inc_ns),
    .cfg_inc_frac(c_cfg_inc_frac),
    .time_set(c_time_set),
    .time_set_ns(c_time_set_ns),
    .time_adj(c_time_adj),
    .time_adj_ns(c_time_adj_ns),
    .time_ns(c_time_ns),
    .gcl_en(c_gcl_en),
    .gcl_base(c_gcl_base),
    .gcl_cycle(c_gcl_cycle),
    .gcl_last(c_gcl_last),
    .gcl_we(c_gcl_we),
    .gcl_waddr(c_gcl_waddr),
    .gcl_wgates(c_gcl_wgates),
    .gcl_wivl(c_gcl_wivl),
    .cbs_en(c_cbs_en),
    .cbs_idle(c_cbs_idle),
    .q_valid(q_valid),
    .q_len(q_len),
    .q_pop(q_pop),
    .tx_start(c_tx_start),
    .tx_tc(tx_tc),
    .tx_len(tx_len),
    .tx_ts(tx_ts),
    .tx_busy(c_tx_busy),
    .gcl_running(c_gcl_running),
    .gcl_entry(c_gcl_entry),
    .gate_state(c_gate_state),
    .cycle_start(c_cycle_start),
    .cbs_credit(c_cbs_credit)
  );

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_CFG0;   // 12'h014 CFG0
  logic [23:0] r_CFG1;   // 12'h018 CFG1
  logic [31:0] r_GCL_BASE0;   // 12'h01C GCL_BASE0
  logic [31:0] r_GCL_BASE1;   // 12'h020 GCL_BASE1
  logic [31:0] r_CBS_IDLE0;   // 12'h024 CBS_IDLE0
  logic [3:0] r_CBS_IDLE1;   // 12'h028 CBS_IDLE1
  logic [30:0] h_GCL_WR;   // 12'h02C GCL_WR holding register
  logic [31:0] h_TIME_SET0;   // 12'h030 TIME_SET0 holding register
  logic [31:0] h_TIME_SET1;   // 12'h034 TIME_SET1 holding register
  logic [31:0] h_TIME_ADJ;   // 12'h038 TIME_ADJ holding register
  logic vld_GCL_WR;
  logic vld_TIME_SET;
  logic vld_TIME_ADJ;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG0 <= 32'h8;
      r_CFG1 <= 24'hF4240;
      r_GCL_BASE0 <= 32'h0;
      r_GCL_BASE1 <= 32'h0;
      r_CBS_IDLE0 <= 32'h0;
      r_CBS_IDLE1 <= 4'h0;
      h_GCL_WR <= '0;
      h_TIME_SET0 <= '0;
      h_TIME_SET1 <= '0;
      h_TIME_ADJ <= '0;
      vld_GCL_WR <= 1'b0;
      vld_TIME_SET <= 1'b0;
      vld_TIME_ADJ <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG0 <= (r_CFG0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_CFG1 <= (r_CFG1 & ~wmask[23:0]) | (PWDATA[23:0] & wmask[23:0]);
      if (wr && hit[7]) r_GCL_BASE0 <= (r_GCL_BASE0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_GCL_BASE1 <= (r_GCL_BASE1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_CBS_IDLE0 <= (r_CBS_IDLE0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_CBS_IDLE1 <= (r_CBS_IDLE1 & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[11]) h_GCL_WR <= (h_GCL_WR & ~wmask[30:0]) | (PWDATA[30:0] & wmask[30:0]);
      vld_GCL_WR <= wr && hit[11];
      if (wr && hit[12]) h_TIME_SET0 <= (h_TIME_SET0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) h_TIME_SET1 <= (h_TIME_SET1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      vld_TIME_SET <= wr && hit[13];
      if (wr && hit[14]) h_TIME_ADJ <= (h_TIME_ADJ & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      vld_TIME_ADJ <= wr && hit[14];
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_inc_ns = r_CFG0[7:0];
  assign c_cfg_inc_frac = r_CFG0[23:8];
  assign c_gcl_en = r_CFG0[24:24];
  assign c_gcl_last = r_CFG0[27:25];
  assign c_cbs_en = r_CFG0[31:28];
  assign c_gcl_cycle = r_CFG1[23:0];
  assign c_gcl_base[31:0] = r_GCL_BASE0[31:0];
  assign c_gcl_base[63:32] = r_GCL_BASE1[31:0];
  assign c_cbs_idle[31:0] = r_CBS_IDLE0[31:0];
  assign c_cbs_idle[35:32] = r_CBS_IDLE1[3:0];
  assign c_gcl_wivl[23:0] = h_GCL_WR[23:0];
  assign c_gcl_wgates[3:0] = h_GCL_WR[27:24];
  assign c_gcl_waddr[2:0] = h_GCL_WR[30:28];
  assign c_time_set_ns[31:0] = h_TIME_SET0[31:0];
  assign c_time_set_ns[63:32] = h_TIME_SET1[31:0];
  assign c_time_adj_ns[31:0] = h_TIME_ADJ[31:0];
  assign c_gcl_we = vld_GCL_WR;
  assign c_time_set = vld_TIME_SET;
  assign c_time_adj = vld_TIME_ADJ;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_cycle_start;
    irq_set[1] = c_tx_start;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG0);
      10'd6: apb_rdata = 32'(r_CFG1);
      10'd7: apb_rdata = 32'(r_GCL_BASE0);
      10'd8: apb_rdata = 32'(r_GCL_BASE1);
      10'd9: apb_rdata = 32'(r_CBS_IDLE0);
      10'd10: apb_rdata = 32'(r_CBS_IDLE1);
      10'd11: apb_rdata = 32'(h_GCL_WR);
      10'd12: apb_rdata = 32'(h_TIME_SET0);
      10'd13: apb_rdata = 32'(h_TIME_SET1);
      10'd14: apb_rdata = 32'(h_TIME_ADJ);
      10'd15: apb_rdata = 32'({c_time_ns[31:0]});
      10'd16: apb_rdata = 32'({c_time_ns[63:32]});
      10'd17: apb_rdata = 32'({c_tx_busy, c_gate_state, c_gcl_entry, c_gcl_running});
      10'd18: apb_rdata = 32'({c_cbs_credit[31:0]});
      10'd19: apb_rdata = 32'({c_cbs_credit[63:32]});
      10'd20: apb_rdata = 32'({c_cbs_credit[79:64]});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
